export {};

export function getOtherCodeSnippet(
	snippet: string,
	richColorsActive: boolean,
	closeButtonActive: boolean
) {
	return `<script>
  ${snippet || ''}
</script>

<!-- ... -->

<Toaster ${richColorsActive ? 'richColors ' : ''} ${closeButtonActive ? 'closeButton ' : ''}/>`;
}

export const usageSnippet = `<script>
  import { Toaster, toast } from 'svelte-sonner'
</script>

<!-- ... -->

<Toaster />
<button onclick={() => toast('My first toast')}>
  Give me a toast
</button>`;

import Icon from './Icon.svelte';
import Loader from './Loader.svelte';
import Toaster from './Toaster.svelte';

export { toast, useSonner } from './toast-state.svelte.js';

export { Icon, Loader, Toaster };

export type { ToastT, ExternalToast, ToasterProps, ToastOptions } from './types.js';

import { SonnerState } from '$lib/toast-state.svelte.js';
import { Context } from 'runed';

export const richColorsContext = new Context<{ setRichColors: (value: boolean) => void }>(
	'richColorsContext'
);

export const sonnerContext = new Context<SonnerState>('<Toaster/>');

export function cn(...classes: (string | undefined)[]) {
	return classes.filter(Boolean).join(' ');
}

export const isBrowser = typeof document !== 'undefined';

export type Expand<T> = T extends object
	? T extends infer O
		? { [K in keyof O]: O[K] }
		: never
	: T;

import { on } from 'svelte/events';

export function useDocumentHidden() {
	let current = $state(typeof document !== 'undefined' ? document.hidden : false);

	$effect(() => {
		return on(document, 'visibilitychange', () => {
			current = document.hidden;
		});
	});

	return {
		get current() {
			return current;
		}
	};
}

import { isBrowser } from './internal/helpers.js';
import type {
	ExternalToast,
	HeightT,
	PromiseData,
	PromiseT,
	AnyComponent,
	ToastT,
	ToastTypes
} from './types.js';
import { sonnerContext } from './internal/ctx.js';
import { untrack } from 'svelte';

let toastsCounter = 0;

// A toast keeps the id it was given, otherwise it gets the next one from the counter.
// `custom` needs the same id `create` would pick, as it hands it to the component.
function getToastId(data?: { id?: number | string }): number | string {
	return typeof data?.id === 'number' || (typeof data?.id === 'string' && data.id.length > 0)
		? data.id
		: toastsCounter++;
}

type UpdateToastProps = {
	id: number | string;
	data: Partial<ToastT>;
	type: ToastTypes;
	message: string | AnyComponent | undefined;
	dismissible: boolean;
};

class ToastState {
	toasts = $state<ToastT[]>([]);
	heights = $state<HeightT[]>([]);
	// Removals whose exit animation is running but whose entry hasn't been removed yet
	#pendingRemovals = new Map<number | string, ReturnType<typeof setTimeout>>();

	#findToastIdx = (id: number | string): number | null => {
		const idx = this.toasts.findIndex((toast) => toast.id === id);
		if (idx === -1) return null;
		return idx;
	};

	#findHeightIdx = (toastId: number | string): number =>
		this.heights.findIndex((height) => height.toastId === toastId);

	addToast = (data: ToastT): void => {
		if (!isBrowser) return;
		this.toasts.unshift(data);
	};

	updateToast = ({ id, data, type, message }: UpdateToastProps): void => {
		const toastIdx = this.toasts.findIndex((toast) => toast.id === id);
		const toastToUpdate = this.toasts[toastIdx];

		this.toasts[toastIdx] = {
			...toastToUpdate,
			...data,
			id,
			title: message,
			type,
			// A dismissal that hasn't been processed yet gets cancelled: the toast is
			// still on screen, so this is an update of it rather than a new toast.
			dismiss: false,
			delete: false,
			updated: true
		};
	};

	// Flags a toast that was dismissed from inside the Toast component (close button,
	// swipe, action/cancel click, auto-close) so `create` treats an id reuse as a new
	// toast instead of merging the old props into it.
	markDismissed = (id: number | string): void => {
		const toastIdx = this.#findToastIdx(id);
		if (toastIdx === null) return;
		const toast = this.toasts[toastIdx];
		if (!toast) return;
		if (!toast.dismiss || !toast.delete) {
			this.toasts[toastIdx] = { ...toast, dismiss: true, delete: true };
		}
	};

	scheduleRemoval = (id: number | string, delay: number): void => {
		this.cancelRemoval(id);
		this.#pendingRemovals.set(
			id,
			setTimeout(() => {
				this.#pendingRemovals.delete(id);
				this.remove(id);
			}, delay)
		);
	};

	cancelRemoval = (id: number | string): void => {
		const timeout = this.#pendingRemovals.get(id);
		if (timeout !== undefined) {
			clearTimeout(timeout);
			this.#pendingRemovals.delete(id);
		}
	};

	create = <T extends AnyComponent>(
		data: ExternalToast<T> & {
			message?: string | T;
			type?: ToastTypes;
			promise?: PromiseT;
		}
	): string | number => {
		const { message, ...rest } = data;
		const id = getToastId(data);

		// Support deprecated `dismissable` as a fallback for backwards compatibility
		const dismissible =
			data.dismissible !== undefined
				? data.dismissible
				: data.dismissable !== undefined
					? data.dismissable
					: true;
		const type = data.type === undefined ? 'default' : data.type;

		untrack(() => {
			// A removal that hasn't run yet gets cancelled: this create() supersedes it,
			// otherwise the old toast's unmount timeout would remove the new one.
			this.cancelRemoval(id);

			const alreadyExists = this.toasts.find((toast) => toast.id === id);

			if (alreadyExists?.dismiss || alreadyExists?.delete) {
				// The previous toast with this id was dismissed, so this is a brand new
				// toast. Drop the old one instead of merging into it, otherwise its
				// props (e.g. `action`) leak into the new one. `updated` makes the still
				// mounted component reset its auto-close timer: when the recreate happens
				// in the same tick as the dismissal, the keyed each reuses the component
				// before it ever processed the dismissal, so the old timer would
				// otherwise keep running.
				this.remove(id);
				this.addToast({
					...rest,
					id,
					title: message,
					dismissible,
					type,
					updated: true
				});
			} else if (alreadyExists) {
				this.updateToast({ id, data, type, message, dismissible });
			} else {
				this.addToast({ ...rest, id, title: message, dismissible, type });
			}
		});

		return id;
	};

	dismiss = (id?: number | string): string | number | undefined => {
		untrack(() => {
			if (id === undefined) {
				// we're dismissing all the active toasts
				this.toasts = this.toasts.map((toast) =>
					toast.dismiss ? toast : { ...toast, dismiss: true }
				);
				return;
			}
			// we're dismissing a specific toast
			const toastIdx = this.toasts.findIndex((toast) => toast.id === id);
			if (this.toasts[toastIdx]) {
				this.toasts[toastIdx] = { ...this.toasts[toastIdx], dismiss: true };
			}
		});
		return id;
	};

	remove = (id?: number | string) => {
		if (id === undefined) {
			// remove all toasts
			this.toasts = [];
			return;
		}
		// remove a specific toast
		const toastIdx = this.#findToastIdx(id);
		if (toastIdx === null) return;
		this.toasts.splice(toastIdx, 1);
		return id;
	};

	message = <T extends AnyComponent>(message: string | T, data?: ExternalToast<T>) => {
		return this.create<T>({ ...data, type: 'default', message });
	};

	error = <T extends AnyComponent>(
		message: string | T,
		data?: ExternalToast<T>
	): string | number => {
		return this.create({ ...data, type: 'error', message });
	};

	success = <T extends AnyComponent>(
		message: string | T,
		data?: ExternalToast<T>
	): string | number => {
		return this.create({ ...data, type: 'success', message });
	};

	info = <T extends AnyComponent>(
		message: string | T,
		data?: ExternalToast<T>
	): string | number => {
		return this.create({ ...data, type: 'info', message });
	};

	warning = <T extends AnyComponent>(
		message: string | T,
		data?: ExternalToast<T>
	): string | number => {
		return this.create({ ...data, type: 'warning', message });
	};

	loading = <T extends AnyComponent>(
		message: string | T,
		data?: ExternalToast<T>
	): string | number => {
		return this.create({ ...data, type: 'loading', message });
	};

	promise = <ToastData>(
		promise: PromiseT<ToastData>,
		data?: PromiseData<ToastData>
	): string | number | undefined => {
		if (!data) {
			// Nothing to show
			return;
		}
		let id: string | number | undefined = undefined;
		if (data.loading !== undefined) {
			id = this.create({
				...data,
				promise,
				type: 'loading',
				message: typeof data.loading === 'string' ? data.loading : data.loading()
			});
		}

		const p = promise instanceof Promise ? promise : promise();

		let shouldDismiss = id !== undefined;

		p.then((response) => {
			if (
				typeof response === 'object' &&
				response &&
				'ok' in response &&
				typeof response.ok === 'boolean' &&
				!response.ok
			) {
				shouldDismiss = false;
				const message = constructPromiseErrorMessage(response);
				this.create({ id, type: 'error', message });
			} else if (data.success !== undefined) {
				shouldDismiss = false;
				const message =
					typeof data.success === 'function' ? data.success(response) : data.success;
				this.create({ id, type: 'success', message });
			}
		})
			.catch((error) => {
				if (data.error !== undefined) {
					shouldDismiss = false;
					const message =
						typeof data.error === 'function' ? data.error(error) : data.error;

					this.create({ id, type: 'error', message });
				}
			})
			.finally(() => {
				if (shouldDismiss) {
					// Toast is still in load state (and will be indefinitely — dismiss it)
					this.dismiss(id);
					id = undefined;
				}

				data.finally?.();
			});

		return id;
	};

	custom = <T extends AnyComponent>(component: T, data?: ExternalToast<T>): string | number => {
		const id = getToastId(data);

		this.create({ component, ...data, id });

		return id;
	};

	removeHeight = (id: number | string) => {
		this.heights = this.heights.filter((height) => height.toastId !== id);
	};

	setHeight = (data: HeightT) => {
		// untrack: setHeight runs inside a $effect; a tracked read of this.heights
		// would re-trigger it on the write below (effect_update_depth_exceeded).
		untrack(() => {
			const heightIdx = this.#findHeightIdx(data.toastId);
			if (heightIdx !== -1) {
				this.heights[heightIdx] = data;
				return;
			}

			// The offset math and --front-toast-height assume heights share the
			// newest-first order of `toasts`, so insert at the matching position.
			// With batched mounts (several toasts created in one tick, or created
			// before the Toaster mounted) the components mount newest-first and a
			// plain unshift would reverse them.
			const order = new Map(this.toasts.map((toast, idx) => [toast.id, idx]));
			const toastOrder = order.get(data.toastId) ?? -1;
			const insertIdx = this.heights.findIndex(
				(height) => (order.get(height.toastId) ?? Infinity) > toastOrder
			);
			if (insertIdx === -1) {
				this.heights.push(data);
			} else {
				this.heights.splice(insertIdx, 0, data);
			}
		});
	};

	reset = () => {
		this.toasts = [];
		this.heights = [];
		this.#pendingRemovals.forEach((timeout) => clearTimeout(timeout));
		this.#pendingRemovals.clear();
	};
}

function constructPromiseErrorMessage(response: unknown) {
	if (response && typeof response === 'object' && 'status' in response) {
		return `HTTP error! Status: ${response.status}`;
	}
	return `Error! ${response}`;
}

export const toastState = new ToastState();

function toastFunction<T extends AnyComponent>(message: string | T, data?: ExternalToast<T>) {
	return toastState.message(message, data);
}

export class SonnerState {
	/**
	 * A derived state of the toasts that are not dismissed.
	 */
	#activeToasts = $derived(toastState.toasts.filter((toast) => !toast.dismiss));

	get toasts() {
		return this.#activeToasts;
	}
}

/**
 * A hook to get a reference to the sonner toast state.
 *
 * Returns a class instance a getter for the `toasts` array.
 *
 * @example
 * ```svelte
 * <script lang="ts">
 *   import { useSonner } from 'svelte-sonner';
 *
 *   const sonner = useSonner();
 *
 *   // Reactive access to the toasts
 *   $effect(() => console.log(sonner.toasts))
 * </script>
 * ```
 */
export function useSonner(): SonnerState {
	return sonnerContext.get();
}

const basicToast = toastFunction;

export const toast = Object.assign(basicToast, {
	success: toastState.success,
	info: toastState.info,
	warning: toastState.warning,
	error: toastState.error,
	custom: toastState.custom,
	message: toastState.message,
	promise: toastState.promise,
	dismiss: toastState.dismiss,
	loading: toastState.loading,
	getActiveToasts: () => {
		return toastState.toasts.filter((toast) => !toast.dismiss);
	}
});

import type { Component, ComponentProps, Snippet } from 'svelte';
import type { Expand } from '$lib/internal/types.js';
import type { HTMLAttributes, HTMLOlAttributes, MouseEventHandler } from 'svelte/elements';

export type FixMe = unknown;

// We need this to consistently be this wide.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type AnyComponent = Component<any, any, string>;

export type ToastTypes =
	| 'normal'
	| 'action'
	| 'success'
	| 'info'
	| 'warning'
	| 'error'
	| 'loading'
	| 'default';

export type PromiseT<Data = unknown> = Promise<Data> | (() => Promise<Data>);

export type PromiseData<ToastData = unknown> = ExternalToast & {
	/**
	 * The loading message or a function that returns the message or
	 * a custom toast component.
	 */
	loading?: string | (() => AnyComponent | string);
	/**
	 * The success message or a function that returns the message or
	 * a custom toast component.
	 */
	success?: string | ((data: ToastData) => AnyComponent | string);
	/**
	 * The error message or a function that returns the message or
	 * a custom toast component.
	 */
	error?: string | ((error: unknown) => AnyComponent | string);
	/**
	 * A function that is called when the promise is finally resolved or rejected.
	 */
	finally?: () => void | Promise<void>;
};

export type ToastAction = {
	label: string | AnyComponent;
	onClick: MouseEventHandler<HTMLButtonElement>;
	actionButtonStyle?: string;
};

export function isAction(action: ToastAction | AnyComponent | undefined): action is ToastAction {
	return (action as ToastAction).label !== undefined;
}

export type ToastT<T extends AnyComponent = AnyComponent> = {
	id: number | string;
	title?: string | AnyComponent;
	type: ToastTypes;
	icon?: AnyComponent | null;
	component?: AnyComponent;
	componentProps?: ComponentProps<T>;
	richColors?: boolean;
	invert?: boolean;
	closeButton?: boolean;
	dismissible?: boolean;
	/**
	 * @deprecated Use `dismissible` instead.
	 */
	dismissable?: boolean;
	important?: boolean;
	description?: string | AnyComponent;
	duration?: number;
	delete?: boolean;
	action?: ToastAction | AnyComponent;
	cancel?: ToastAction | AnyComponent;
	onDismiss?: (toast: ToastT) => void;
	onAutoClose?: (toast: ToastT) => void;
	promise?: PromiseT;
	cancelButtonStyle?: string;
	actionButtonStyle?: string;
	style?: string;
	unstyled?: boolean;
	class?: string;
	classes?: ToastClasses;
	descriptionClass?: string;
	position?: Position;
	/**
	 * The id of the `<Toaster />` this toast should be rendered in. Toasts without
	 * a `toasterId` render in the toaster without an `id`.
	 */
	toasterId?: string;
	dismiss?: boolean;
	/**
	 * @internal This is used to determine if the toast has been updated to determine when to reset timer. Hacky but works.
	 */
	updated?: boolean;
};

export type Position =
	| 'top-left'
	| 'top-right'
	| 'bottom-left'
	| 'bottom-right'
	| 'top-center'
	| 'bottom-center';

export type HeightT = {
	height: number;
	toastId: number | string;
	toasterId?: string;
	position?: Position;
};

export type Theme = 'light' | 'dark';

export type ToastToDismiss = {
	id: number | string;
	dismiss: boolean;
};

export type ExternalToast<T extends AnyComponent = AnyComponent> = Omit<
	ToastT<T>,
	'id' | 'type' | 'title' | 'promise' | 'updated'
> & {
	id?: number | string;
};

type Offset =
	| {
			top?: string | number;
			right?: string | number;
			bottom?: string | number;
			left?: string | number;
	  }
	| string
	| number;

export type ToastIcon = Snippet | null;

type ToastIcons = {
	/**
	 * The icon to use for the success toast,
	 * can be either a snippet, a component, or `null` to not render an icon.
	 */
	successIcon?: ToastIcon;

	/**
	 * The icon to use for the info toast,
	 * can be either a snippet, a component, or `null` to not render an icon.
	 */
	infoIcon?: ToastIcon;

	/**
	 * The icon to use for the warning toast,
	 * can be either a snippet, a component, or `null` to not render an icon.
	 */
	warningIcon?: ToastIcon;

	/**
	 * The icon to use for the error toast,
	 * can be either a snippet, a component, or `null` to not render an icon.
	 */
	errorIcon?: ToastIcon;

	/**
	 * The icon to use for the loading toast,
	 * can be either a snippet, a component, or `null` to not render an icon.
	 */
	loadingIcon?: ToastIcon;

	/**
	 * The icon to use for the close button,
	 * can be either a snippet, a component, or `null` to not render an icon.
	 */
	closeIcon?: ToastIcon;
};

export type ToasterProps = {
	/**
	 * Identifies this toaster so toasts can target it via `toast(..., { toasterId })`.
	 * A toaster without an `id` renders only the toasts without a `toasterId`.
	 */
	id?: string;

	/**
	 * Dark toasts in light mode and vice versa.
	 *
	 * @default false
	 */
	invert?: boolean;

	/**
	 * Toast's theme, either light, dark, or system.
	 *
	 * If using [mode-watcher](https://mode-watcher.sveco.dev), you can set this to the
	 * `userPrefersMode.current` to automatically switch themes based on those preferences.
	 *
	 * @default 'light'
	 */
	theme?: 'light' | 'dark' | 'system';

	/**
	 * Place where the toasts will be rendered
	 *
	 * @default 'bottom-right'
	 */
	position?: Position;

	/**
	 * Keyboard shortcut that will move focus to the toaster area.
	 *
	 * @default '⌥/alt + T'
	 */
	hotkey?: string[];

	/**
	 * Makes error and success state more colorful
	 *
	 * @default false
	 */
	richColors?: boolean;

	/**
	 * Toasts will be expanded by default
	 *
	 * @default false
	 */
	expand?: boolean;

	/**
	 * The duration of the toast in milliseconds.
	 *
	 * @default 4000
	 */
	duration?: number;

	/**
	 * Gap between toasts when expanded, in pixels.
	 *
	 * @default '14px'
	 */
	gap?: number;

	/**
	 * Amount of visible toasts
	 *
	 * @default 3
	 */
	visibleToasts?: number;

	/**
	 * Adds a close button to all toasts, shows on hover
	 *
	 * @default false
	 */
	closeButton?: boolean;

	/**
	 * These will act as default options for all toasts.
	 *
	 * @default {}
	 */
	toastOptions?: ToastOptions;

	/**
	 * Offset from the edges of the screen.
	 *
	 * @default '32px'
	 */
	offset?: Offset;

	/**
	 * Offset from the edges of the screen for mobile devices.
	 *
	 * @default '16px'
	 */
	mobileOffset?: Offset;

	/**
	 * Pause the toast timer when the page is hidden, e.g. when the user switches
	 * tabs. Toasts will not expire while the page is hidden.
	 *
	 * @default false
	 */
	pauseWhenPageIsHidden?: boolean;

	/**
	 * Directionality of toast's text
	 *
	 * @default 'auto'
	 */
	dir?: 'ltr' | 'rtl' | 'auto';

	/**
	 * The directions in which the toast can be swiped.
	 *
	 * @default ['top', 'right', 'bottom', 'left']
	 */
	swipeDirections?: SwipeDirection[];

	/**
	 * The aria-label to use for the container element, which will
	 * be combined with the hotkey, if provided like so:
	 *
	 * ```svelte
	 * <section aria-label="{containerAriaLabel} {hotkeyLabel}"
	 * </section>
	 * ```
	 *
	 * @default 'Notifications'
	 */
	containerAriaLabel?: string;

	/**
	 * The aria label for the close button.
	 *
	 * @default 'Close toast'
	 */
	closeButtonAriaLabel?: string;
} & HTMLOlAttributes &
	ToastIcons;

export type ToastOptions = {
	/**
	 * The classes applied to the toast element.
	 */
	class?: string;

	/**
	 * The classes applied to the toast description element.
	 */
	descriptionClass?: string;

	/**
	 * The CSS styles applied to the toast element.
	 */
	style?: string;

	/**
	 * The CSS styles applied to the cancel button element.
	 */
	cancelButtonStyle?: string;

	/**
	 * The CSS styles applied to the action button element.
	 */
	actionButtonStyle?: string;

	/**
	 * The duration of the toast in milliseconds.
	 */
	duration?: number;

	/**
	 * Whether the toast should be unstyled or not.
	 */
	unstyled?: boolean;

	/**
	 * Classes to apply to the various elements of the toast.
	 */
	classes?: Expand<ToastClasses>;

	/**
	 * The aria label for the close button.
	 */
	closeButtonAriaLabel?: string;

	/**
	 * Whether to show the close button.
	 */
	closeButton?: boolean;
};

/**
 * The classes applied to the various elements of the toast.
 */
export type ToastClasses = {
	toast?: string;
	title?: string;
	description?: string;
	loader?: string;
	closeButton?: string;
	cancelButton?: string;
	actionButton?: string;
	icon?: string;
	content?: string;
} & ToastTypeClasses;

type ToastTypeClasses = Partial<Record<ToastTypes, string>>;

export type SwipeDirection = 'top' | 'right' | 'bottom' | 'left';

export type ToastProps = {
	toast: ToastT;
	index: number;
	swipeDirections?: SwipeDirection[];
	gap?: number;
	expanded: boolean;
	invert: boolean;
	position: Position;
	visibleToasts: number;
	expandByDefault: boolean;
	closeButton: boolean;
	interacting: boolean;
	cancelButtonStyle: string;
	actionButtonStyle: string;
	duration: number;
	class: string;
	descriptionClass: string;
	classes: ToastClasses;
	unstyled: boolean;
	closeButtonAriaLabel: string;
	defaultRichColors: boolean;
	pauseWhenPageIsHidden: boolean;
} & HTMLAttributes<HTMLLIElement> &
	ToastIcons;

// Client-only so query params drive the page and `toast()` calls made during
// component init exercise the real pre-mount path in the browser.
export const ssr = false;

import { describe, it } from 'vitest';
import PropsToastTest from './PropsToastTest.svelte';
import TestIcon from './TestIcon.svelte';
import { render, waitFor } from '@testing-library/svelte';
import { userEvent } from '@testing-library/user-event';
import { toast, toastState } from '$lib/toast-state.svelte.js';
import { sleep } from './utils.js';
import type { ToasterProps } from '$lib/index.js';

function setup(props: { cb: (t: typeof toast) => void } & ToasterProps) {
	const user = userEvent.setup();
	const returned = render(PropsToastTest, { props });
	const trigger = returned.getByTestId('trigger');

	return {
		trigger,
		user,
		...returned
	};
}

describe('Toast lifecycle', () => {
	beforeEach(() => {
		toastState.reset();
	});

	it('renders a custom icon only once in a settled promise toast', async () => {
		let resolve: (value: string) => void;
		const promise = new Promise<string>((res) => {
			resolve = res;
		});

		const { user, trigger, getAllByTestId, getByText } = setup({
			cb: (toast) => {
				toast.promise(promise, {
					loading: 'Loading...',
					success: 'Loaded',
					icon: TestIcon
				});
			}
		});

		await user.click(trigger);
		expect(getByText('Loading...')).toBeVisible();

		resolve!('done');
		await waitFor(() => expect(getByText('Loaded')).toBeVisible());
		expect(getAllByTestId('custom-icon').length).toBe(1);
	});

	it('hides default icons from assistive technology', async () => {
		const { user, trigger, container } = setup({
			cb: (toast) => toast.success('Success toast', { closeButton: true })
		});

		await user.click(trigger);

		const typeIcon = container.querySelector('[data-sonner-toast] [data-icon] svg');
		expect(typeIcon).toHaveAttribute('aria-hidden', 'true');

		const closeIcon = container.querySelector('[data-sonner-toast] [data-close-button] svg');
		expect(closeIcon).toHaveAttribute('aria-hidden', 'true');
	});

	it('clears the loading state when toast() reuses the id of a loading toast', async () => {
		const { user, trigger, container, getByText } = setup({
			cb: (toast) => {
				const id = toast.loading('Loading forever');
				setTimeout(() => toast('Done', { id }), 100);
			}
		});

		await user.click(trigger);
		expect(container.querySelector('[data-sonner-toast]')).toHaveAttribute(
			'data-type',
			'loading'
		);

		await sleep(200);
		expect(getByText('Done')).toBeVisible();
		expect(container.querySelector('[data-sonner-toast]')).toHaveAttribute(
			'data-type',
			'default'
		);
	});

	it('clears the loading state when toast.custom() reuses the id of a loading toast', async () => {
		const { user, trigger, container } = setup({
			cb: (toast) => {
				const id = toast.loading('Loading forever');
				setTimeout(() => toast.custom(TestIcon, { id }), 100);
			}
		});

		await user.click(trigger);
		expect(container.querySelector('[data-sonner-toast]')).toHaveAttribute(
			'data-type',
			'loading'
		);

		await sleep(200);
		expect(container.querySelector('[data-sonner-toast]')).not.toHaveAttribute(
			'data-type',
			'loading'
		);
	});

	it('does not leak props into a new toast reusing a dismissed toast id', async () => {
		const { user, trigger, getByText, queryByText } = setup({
			cb: (toast) => {
				const id = toast('With action', {
					action: { label: 'Undo', onClick: () => {} }
				});
				toast.dismiss(id);
				toast('Without action', { id });
			}
		});

		await user.click(trigger);
		await waitFor(() => expect(getByText('Without action')).toBeVisible());
		expect(queryByText('Undo')).toBeNull();
	});

	it('keeps a toast recreated during the exit animation window on screen', async () => {
		const { user, trigger, getByText } = setup({
			cb: (toast) => {
				const id = toast('Original toast');
				toast.dismiss(id);
				// recreate while the 200ms exit-animation removal is still pending
				setTimeout(() => toast('Remounted toast', { id }), 100);
			}
		});

		await user.click(trigger);
		await sleep(500);
		expect(getByText('Remounted toast')).toBeVisible();
		expect(document.querySelector('[data-sonner-toast][data-removed="true"]')).toBeNull();
	});

	it('resets the auto-close timer when a dismissed id is recreated in the same tick', async () => {
		const { user, trigger, getByText, queryByText } = setup({
			cb: (toast) => {
				const id = toast('Short toast', { duration: 100 });
				setTimeout(() => {
					toast.dismiss(id);
					toast('Longer toast', { id, duration: 600 });
				}, 50);
			}
		});

		await user.click(trigger);

		// The short toast's 100ms timer would remove the replacement at ~150ms
		// if the recreate didn't reset it
		await sleep(400);
		expect(getByText('Longer toast')).toBeVisible();

		// The replacement's own 600ms duration still applies
		await waitFor(() => expect(queryByText('Longer toast')).toBeNull());
	});

	it('treats an id reused after a close-button dismissal as a new toast', async () => {
		let onDismissCalls = 0;
		let toastId: string | number;
		const { user, trigger, container, getByText, queryByText } = setup({
			cb: (toast) => {
				toastId = toast('Closable toast', {
					closeButton: true,
					action: { label: 'Undo', onClick: () => {} },
					onDismiss: () => onDismissCalls++
				});
			}
		});

		await user.click(trigger);
		expect(getByText('Closable toast')).toBeVisible();

		const closeButton = container.querySelector<HTMLButtonElement>('[data-close-button]');
		await user.click(closeButton!);
		expect(onDismissCalls).toBe(1);

		toast('Recreated toast', { id: toastId! });
		await waitFor(() => expect(getByText('Recreated toast')).toBeVisible());
		expect(queryByText('Undo')).toBeNull();
		expect(onDismissCalls).toBe(1);
	});

	it('keeps an explicit id of 0 in toast.custom()', async () => {
		let returnedId: string | number | undefined;
		const { user, trigger } = setup({
			cb: (toast) => {
				returnedId = toast.custom(TestIcon, { id: 0 });
			}
		});

		await user.click(trigger);
		expect(returnedId).toBe(0);
		expect(toastState.toasts[0]?.id).toBe(0);
	});
});

import { describe, it } from 'vitest';
import ToastTest from './ToastTest.svelte';
import { render, waitFor } from '@testing-library/svelte';
import { userEvent } from '@testing-library/user-event';
import { toast, toastState } from '$lib/toast-state.svelte.js';
import { sleep } from './utils.js';

function setup(props: { cb: (t: typeof toast) => void }) {
	const user = userEvent.setup();
	const returned = render(ToastTest, { props });
	const trigger = returned.getByTestId('trigger');

	return {
		trigger,
		user,
		...returned
	};
}

describe('Toast', () => {
	beforeEach(() => {
		toastState.reset();
	});

	it('should show a toast', async () => {
		const { user, trigger, container, getByText } = setup({
			cb: (toast) => toast('Hello world')
		});

		await user.click(trigger);
		expect(getByText('Hello world')).toBeVisible();

		const toasts = Array.from(container.querySelectorAll<HTMLElement>('[data-sonner-toast]'));
		expect(toasts.length).toBe(1);
	});

	it('should show a toast with a custom duration', async () => {
		const { user, trigger, queryByText } = setup({
			cb: (toast) => toast('Hello world', { duration: 300 })
		});

		expect(queryByText('Hello world')).toBeNull();

		await user.click(trigger);
		await waitFor(() => expect(queryByText('Hello world')).not.toBeNull());

		// duration (300ms) + exit animation (200ms), with margin for slow runs
		await waitFor(() => expect(queryByText('Hello world')).toBeNull());
	});

	it('should focus the toast when hotkey is pressed', async () => {
		const { user, trigger, getByText } = setup({
			cb: (toast) => toast('Hello world', { duration: 5000 })
		});

		await user.click(trigger);
		expect(getByText('Hello world')).toBeVisible();

		await user.keyboard('{Alt>}T{/Alt}');
		await sleep(100);
		expect(document.activeElement).toBeInstanceOf(HTMLOListElement);
	});

	it('should not immediately close the toast when reset', async () => {
		const { user, trigger, getByText, queryByText } = setup({
			cb: (toast) => {
				const id = toast('Loading', { duration: 4000 });

				setTimeout(() => {
					toast.success('Finished loading!', { id });
				}, 1000);
			}
		});

		await user.click(trigger);
		expect(getByText('Loading')).toBeVisible();
		await sleep(2050);
		expect(queryByText('Loading')).toBeNull();
		expect(getByText('Finished loading!')).toBeVisible();
		await sleep(1000);
		expect(getByText('Finished loading!')).toBeVisible();
	});

	it('should reset duration on a toast update', async () => {
		const { user, trigger, getByText, queryByText } = setup({
			cb: (toast) => {
				const id = toast('Loading', { duration: 1000 });

				setTimeout(() => {
					toast.success('Finished loading!', { id });
				}, 750);
			}
		});

		await user.click(trigger);
		expect(getByText('Loading')).toBeVisible();
		await sleep(800);
		expect(queryByText('Loading')).toBeNull();
		expect(getByText('Finished loading!')).toBeVisible();
		// there would only be ~.5 second left on the original toast
		// so we're gonna wait 2 seconds to make sure the timer is reset
		await sleep(600);
		expect(getByText('Finished loading!')).toBeVisible();
		// finally we'll wait another 1500ms to make sure the toast closes after 2 seconds
		// since the original toast had a duration of 2 seconds
		await sleep(600);
		expect(queryByText('Finished loading!')).toBeNull();
	});

	it('should allow duration updates on toast update', async () => {
		const { user, trigger, getByText, queryByText } = setup({
			cb: (toast) => {
				const id = toast('Loading', { duration: 2000 });

				setTimeout(() => {
					toast.success('Finished loading!', { id, duration: 4000 });
				}, 1000);
			}
		});

		await user.click(trigger);
		expect(getByText('Loading')).toBeVisible();
		await sleep(1200);
		expect(queryByText('Loading')).toBeNull();
		expect(getByText('Finished loading!')).toBeVisible();
		await sleep(2200);
		expect(getByText('Finished loading!')).toBeVisible();
	});
});

import { describe, it } from 'vitest';
import PropsToastTest from './PropsToastTest.svelte';
import MultiToasterTest from './MultiToasterTest.svelte';
import { render, waitFor } from '@testing-library/svelte';
import { userEvent } from '@testing-library/user-event';
import { toast, toastState } from '$lib/toast-state.svelte.js';
import { sleep } from './utils.js';
import type { ToasterProps } from '$lib/index.js';

function setup(props: { cb: (t: typeof toast) => void } & ToasterProps) {
	const user = userEvent.setup();
	const returned = render(PropsToastTest, { props });
	const trigger = returned.getByTestId('trigger');

	return {
		trigger,
		user,
		...returned
	};
}

describe('Toaster', () => {
	beforeEach(() => {
		toastState.reset();
	});

	it('applies classes.default only to toasts without a type', async () => {
		const { user, trigger, container } = setup({
			cb: (toast) => {
				toast('Plain toast');
				toast.success('Success toast');
			},
			toastOptions: {
				classes: {
					default: 'default-toast-class',
					success: 'success-toast-class'
				}
			}
		});

		await user.click(trigger);

		const plain = container.querySelector('[data-sonner-toast][data-type="default"]');
		const success = container.querySelector('[data-sonner-toast][data-type="success"]');

		expect(plain).toHaveClass('default-toast-class');
		expect(success).toHaveClass('success-toast-class');
		expect(success).not.toHaveClass('default-toast-class');
	});

	it('shows a toast created before the Toaster mounts', async () => {
		toast('Created before mount');

		const { getByText } = setup({ cb: () => {} });

		await waitFor(() => expect(getByText('Created before mount')).toBeVisible());
	});

	it('routes toasts to the toaster matching their toasterId', async () => {
		const user = userEvent.setup();
		const { getByTestId } = render(MultiToasterTest, {
			props: {
				cb: () => {
					toast('For the default toaster');
					toast('For the named toaster', { toasterId: 'secondary' });
				}
			}
		});

		await user.click(getByTestId('trigger'));

		const defaultToaster = getByTestId('default-toaster');
		const namedToaster = getByTestId('named-toaster');

		expect(defaultToaster).toHaveTextContent('For the default toaster');
		expect(defaultToaster).not.toHaveTextContent('For the named toaster');
		expect(namedToaster).toHaveTextContent('For the named toaster');
		expect(namedToaster).not.toHaveTextContent('For the default toaster');
	});

	it('dismisses toasts across all toasters with toast.dismiss()', async () => {
		const user = userEvent.setup();
		const { getByTestId } = render(MultiToasterTest, {
			props: {
				cb: () => {
					toast('Default toast');
					toast('Named toast', { toasterId: 'secondary' });
					setTimeout(() => toast.dismiss(), 100);
				}
			}
		});

		await user.click(getByTestId('trigger'));
		expect(getByTestId('default-toaster')).toHaveTextContent('Default toast');

		await sleep(500);
		expect(
			document.querySelectorAll('[data-sonner-toast]:not([data-removed="true"])').length
		).toBe(0);
	});

	it('registers heights newest-first when toasts mount in the same tick', async () => {
		let olderId: string | number;
		let newerId: string | number;
		const { user, trigger } = setup({
			cb: (toast) => {
				olderId = toast('Older toast');
				newerId = toast('Newer toast');
			}
		});

		await user.click(trigger);

		await waitFor(() => expect(toastState.heights.length).toBe(2));
		expect(toastState.heights.map((height) => height.toastId)).toEqual([newerId!, olderId!]);
	});

	it('uses the gap prop in the offset math', async () => {
		const { user, trigger, container } = setup({
			cb: (toast) => {
				toast('First toast');
				toast('Second toast');
			},
			gap: 20
		});

		await user.click(trigger);

		const offsets = Array.from(
			container.querySelectorAll<HTMLElement>('[data-sonner-toast]')
		).map((el) => el.style.getPropertyValue('--offset'));

		// jsdom measures zero heights, so the non-front toast's offset is exactly the gap
		expect(offsets).toContain('20px');
	});

	it('shows the close button when set via toastOptions', async () => {
		const { user, trigger, container } = setup({
			cb: (toast) => toast('With close button'),
			toastOptions: { closeButton: true }
		});

		await user.click(trigger);
		expect(container.querySelector('[data-close-button]')).not.toBeNull();
	});
});

export function sleep(ms: number) {
	return new Promise((resolve) => setTimeout(resolve, ms));
}
